update public.spell_catalog set name_ru='Поиск ловушек', casting_time='Действие', spell_range='120 футов', area='В пределах линии обзора', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Определяешь наличие ловушек в пределах дистанции и линии обзора, а также общий характер угрозы. Точное местоположение не раскрывается.', upcast='', notes='Считает ловушками намеренно созданные источники опасности: механические или магические. Не обнаруживает естественные провалы, слабый потолок или скрытую воронку.', author_description='Заклинание сообщает, что где-то впереди есть ловушка. Где именно — не говорит. Магия, которая умеет тревожить, но отказывается быть полезной до конца.', author_comment='«Ловушка есть». Спасибо. Плут за те же деньги хотя бы ещё украдёт твой кошелёк.' where slug='find-traps';
update public.spell_catalog set name_ru='Пламенный клинок', casting_time='Бонусное действие', spell_range='На себя', area='На себя', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='лист сумаха', check_type='Рукопашная атака заклинанием', damage='3к6 + модификатор характеристики заклинаний огнём', effect_summary='Создаёшь в свободной руке клинок из огня. Действием Магии можно атаковать им в ближнем бою. Если отпустишь, клинок исчезнет, но его можно вызвать снова бонусным действием.', upcast='+1к6 урона за каждый уровень ячейки выше 2.', notes='Клинок даёт яркий свет на 10 футов и тусклый ещё на 10.', author_description='Друид наконец признаёт, что иногда природу удобнее держать в форме меча. Горит красиво, режет плохо, зато объяснять медведю технику безопасности не надо.', author_comment='Если ты создал огненный меч и всё равно проиграл спор воину, не рассказывай никому.' where slug='flame-blade';
update public.spell_catalog set name_ru='Пылающая сфера', casting_time='Действие', spell_range='60 футов', area='Сфера диаметром 5 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='шарик воска', check_type='Спасбросок Ловкости', damage='2к6 огнём; половина при успехе', effect_summary='Создаёшь огненную сферу на земле. Существо, заканчивающее ход в 5 футах от неё, делает спасбросок. Бонусным действием сферу можно катить до 30 футов; при входе в пространство существа оно сразу делает спасбросок, а сфера останавливается.', upcast='+1к6 урона за каждый уровень ячейки выше 2.', notes='Сфера перепрыгивает ямы до 10 футов и препятствия до 5 футов. Поджигает незакреплённые горючие предметы.', author_description='Катящийся огненный шар, который преследует людей и поджигает мебель. Волшебники называют это контролем пространства. Владельцы таверн используют другие слова.', author_comment='Если сфера застряла в дверях, возможно, это единственный член партии, который вовремя остановился.' where slug='flaming-sphere';
update public.spell_catalog set name_ru='Нетленность', casting_time='Действие', spell_range='Касание', area='1 труп или останки', duration='10 дней', components=array['В','С','М'], material='2 медные монеты, расходуются', check_type='', damage='', effect_summary='Защищает труп или останки от разложения и превращения в нежить на 10 дней. Дни под действием заклинания не считаются в лимит времени для некоторых заклинаний возвращения к жизни.', upcast='', notes='Материалы расходуются.', author_description='Две медяки, чтобы труп десять дней сохранял товарный вид. Смерть, как выясняется, тоже умеет работать по подписке.', author_comment='Если вы уже обсуждаете сроки хранения тела, поход явно пошёл не по плану.' where slug='gentle-repose';
update public.spell_catalog set name_ru='Порыв ветра', casting_time='Действие', spell_range='На себя', area='Линия 60 × 10 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='семя бобового растения', check_type='Спасбросок Силы', damage='', effect_summary='Создаёшь линию сильного ветра. Существо в линии при провале спасброска отталкивается на 15 футов. Тот, кто заканчивает ход в линии, делает спасбросок снова. Движение к тебе внутри линии стоит вдвое дороже.', upcast='', notes='Рассеивает газ и пар, гасит незащищённое пламя и с шансом 50% — защищённое. Бонусным действием можно менять направление линии.', author_description='Шестьдесят футов ветра для тех случаев, когда просьба «отойди» уже исчерпала дипломатический потенциал.', author_comment='Отлично сдувает дым, газ и уверенность врага в собственной устойчивости.' where slug='gust-of-wind';
update public.spell_catalog set name_ru='Нагрев металла', casting_time='Действие', spell_range='60 футов', area='1 изготовленный металлический объект', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='кусок железа и пламя', check_type='Если держит/носит и получает урон: спасбросок Телосложения', damage='2к8 огнём при наложении и повторно бонусным действием', effect_summary='Раскаляет видимый металлический предмет. Существо, касающееся его, получает урон сразу; затем бонусным действием можно повторять урон каждый ход, пока предмет в пределах дистанции.', upcast='+1к8 урона за каждый уровень ячейки выше 2.', notes='Если существо держит или носит предмет и получает урон, при провале спасброска оно роняет предмет, если может; иначе получает помеху на атаки и проверки характеристик до начала следующего хода.', author_description='Выбираешь металлическую броню и превращаешь её в переносную печь. Друиды любят напоминать, что природа терпелива. А потом делают вот это.', author_comment='Снять тяжёлый доспех быстро нельзя. Именно поэтому это заклинание такое воспитательное.' where slug='heat-metal';
update public.spell_catalog set name_ru='Удержание личности', casting_time='Действие', spell_range='60 футов', area='1 гуманоид', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='прямой кусочек железа', check_type='Спасбросок Мудрости; повтор в конце каждого хода', damage='', effect_summary='При провале гуманоид становится Парализованным. В конце каждого своего хода повторяет спасбросок, заканчивая эффект при успехе.', upcast='+1 гуманоид за каждый уровень ячейки выше 2.', notes='Работает только на гуманоидов.', author_description='Человек перестаёт двигаться. Всё. Иногда самые страшные заклинания не нуждаются в огне, громких словах и длинной теории.', author_comment='Насилие не решает проблем. Паралич, правда, иногда значительно упрощает дальнейшее обсуждение.' where slug='hold-person';
update public.spell_catalog set name_ru='Невидимость', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='ресница в гуммиарабике', check_type='', damage='', effect_summary='Цель становится Невидимой до окончания заклинания.', upcast='+1 цель за каждый уровень ячейки выше 2.', notes='Эффект заканчивается сразу после того, как цель совершит бросок атаки, нанесёт урон или сотворит заклинание.', author_description='Становишься невидимым, пока не решишь испортить всё атакой, уроном или магией. То есть для большинства приключенцев — ненадолго.', author_comment='Если невидимый плут говорит, что просто «осмотрится», проверь карманы заранее.' where slug='invisibility';
update public.spell_catalog set name_ru='Стук', casting_time='Действие', spell_range='60 футов', area='1 запертый или закрытый объект', duration='Мгновенно', components=array['В'], material=null, check_type='', damage='', effect_summary='Открывает один обычный замок, засов или застрявший механизм. Магический замок подавляется на 10 минут.', upcast='', notes='После применения раздаётся громкий стук, слышимый на расстоянии до 300 футов. Если на объекте несколько замков, открывается только один.', author_description='Открывает дверь без ключа и одновременно объявляет об этом всем в радиусе трёхсот футов. Волшебник решил заменить плута, но забыл про слово «тихо».', author_comment='Поздравляю: дверь открыта. И теперь вся крепость знает, что вы пришли.' where slug='knock';
update public.spell_catalog set name_ru='Малое восстановление', casting_time='Бонусное действие', spell_range='Касание', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Снимает с цели одно состояние на выбор: Ослепление, Глухоту, Паралич или Отравление.', upcast='', notes='Не лечит урон и не снимает другие состояния.', author_description='Быстро исправляет четыре неприятных состояния. Жрец потом обязательно скажет, что это чудо. Воин с нормальной аптечкой хотя бы не требует верить в чудеса.', author_comment='Полезно. Ненавижу признавать, когда жрец действительно полезен.' where slug='lesser-restoration';
update public.spell_catalog set name_ru='Левитация', casting_time='Действие', spell_range='60 футов', area='1 существо или свободный предмет до 500 фунтов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='металлическая пружина', check_type='Нежелающее существо: спасбросок Телосложения', damage='', effect_summary='Поднимает цель вертикально до 20 футов и удерживает в воздухе. Высоту можно менять до 20 футов за ход. Существо без опоры может двигаться только отталкиваясь от неподвижных поверхностей.', upcast='', notes='Если заклинатель не является целью, перемещение цели требует действия Магии и цель должна оставаться в пределах дистанции. После окончания цель плавно опускается.', author_description='Поднимаешь человека в воздух и оставляешь там переосмысливать жизненные решения. Удивительно терапевтичная школа преобразования.', author_comment='Если враг висит под потолком и ругается, заклинание работает.' where slug='levitate';
update public.spell_catalog set name_ru='Поиск животных или растений', casting_time='Действие', spell_range='На себя', area='Радиус поиска 5 миль', duration='Мгновенно', components=array['В','С','М'], material='шерсть ищейки', check_type='', damage='', effect_summary='Называешь или описываешь конкретный вид зверя, растительного существа или немагического растения и узнаёшь направление и расстояние до ближайшего такого объекта в пределах 5 миль.', upcast='', notes='Ритуал.', author_description='Пять миль поиска нужного зверя или растения. Следопыт обычно делает примерно то же самое ногами, но магия удобнее для людей, которые не хотят пачкать сапоги.', author_comment='Если ищешь ядовитое растение, уточни заранее, ты его собираешься есть или это опять друидская наука.' where slug='locate-animals-or-plants';
update public.spell_catalog set name_ru='Поиск предмета', casting_time='Действие', spell_range='На себя', area='Радиус поиска 1000 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='раздвоенная веточка', check_type='', damage='', effect_summary='Узнаёшь направление к знакомому предмету в пределах 1000 футов. Если он движется, узнаёшь направление движения. Можно искать конкретный предмет, который видел вблизи, или ближайший предмет определённого типа.', upcast='', notes='Любая толщина свинца на прямом пути блокирует поиск.', author_description='Магическое «где я это положил?» на тысячу футов. Возможно, величайшее достижение волшебников после карманов.', author_comment='Не ищет здравый смысл. Проверяли.' where slug='locate-object';
update public.spell_catalog set name_ru='Волшебные уста', casting_time='Действие', spell_range='30 футов', area='1 непереносимый объект', duration='До рассеивания', components=array['В','С','М'], material='нефритовая пыль стоимостью 10+ зм, расходуется', check_type='', damage='', effect_summary='Записываешь в объект сообщение до 25 слов и задаёшь визуальное или звуковое условие срабатывания в пределах 30 футов. При выполнении условия на объекте появляются магические уста и произносят сообщение твоим голосом.', upcast='', notes='Материал расходуется. Сообщение может длиться до 10 минут. Можно настроить одноразовое срабатывание или повторение при каждом выполнении условия.', author_description='Заставляешь предмет говорить твоим голосом при заданном условии. Наконец можно оставить саркастический комментарий даже там, где тебя физически нет.', author_comment='Лучшее применение магии — сделать так, чтобы сундук сам говорил плуту «не трогай». Он всё равно тронет.' where slug='magic-mouth';
update public.spell_catalog set name_ru='Магическое оружие', casting_time='Бонусное действие', spell_range='Касание', area='1 немагическое оружие', duration='1 час', components=array['В','С'], material=null, check_type='', damage='+1 к броскам атаки и урона', effect_summary='Немагическое оружие становится магическим и получает +1 к броскам атаки и урона.', upcast='Ячейка 3–5 уровня: бонус +2. Ячейка 6+ уровня: бонус +3.', notes='Заклинание заканчивается раньше, если сотворить его снова.', author_description='Берёшь обычное оружие и временно делаешь его лучше. Воин одобряет: наконец маг потратил ячейку на что-то, что не взрывает друзей.', author_comment='Редкий случай, когда после слов «я зачарую твой меч» действительно становится спокойнее.' where slug='magic-weapon';
update public.spell_catalog set name_ru='Ментальный шип', casting_time='Действие', spell_range='120 футов', area='1 видимое существо', duration='Концентрация, до 1 часа', components=array['С'], material=null, check_type='Спасбросок Мудрости', damage='3к8 психического урона; половина при успехе', effect_summary='Поражает разум цели. При провале спасброска кроме полного урона ты до конца заклинания знаешь её местоположение на том же плане; она не может скрыться от тебя, а её Невидимость против тебя бесполезна.', upcast='+1к8 урона за каждый уровень ячейки выше 2.', notes='Отслеживание работает только при провале спасброска и пока обе цели на одном плане существования.', author_description='Вбиваешь в чужую голову маяк, который ещё и болит. Очень убедительный аргумент против попытки сбежать.', author_comment='Если после этого цель всё равно убегает, уважай хотя бы её целеустремлённость.' where slug='mind-spike';
update public.spell_catalog set name_ru='Зеркальное отражение', casting_time='Действие', spell_range='На себя', area='На себя', duration='1 минута', components=array['В','С'], material=null, check_type='При попадании по тебе: к6 за каждую оставшуюся копию; любой результат 3+ перенаправляет удар в копию', damage='', effect_summary='Создаёт три иллюзорные копии. Когда атака попадает по тебе, бросаешь к6 за каждую оставшуюся копию; если хотя бы один результат 3+, вместо тебя уничтожается одна копия.', upcast='', notes='Не действует на существо с Ослеплением, слепым зрением или истинным зрением. Копии игнорируют прочий урон и эффекты.', author_description='Три копии тебя бегают рядом и добровольно принимают удары. Самый преданный состав группы, который маг когда-либо соберёт.', author_comment='Копии не спорят, не воруют пайки и умирают вместо тебя. Почти идеальные товарищи.' where slug='mirror-image';
update public.spell_catalog set name_ru='Туманный шаг', casting_time='Бонусное действие', spell_range='На себя', area='Телепортация до 30 футов', duration='Мгновенно', components=array['В'], material=null, check_type='', damage='', effect_summary='Телепортируешься на расстояние до 30 футов в свободное место, которое видишь.', upcast='', notes='Не требует концентрации.', author_description='Тридцать футов мгновенного перемещения. Идеально, когда осознание ошибки пришло раньше, чем меч противника.', author_comment='Самая полезная магия волшебника часто начинается со слов: «мне надо отсюда уйти».' where slug='misty-step';
update public.spell_catalog set name_ru='Лунный луч', casting_time='Действие', spell_range='120 футов', area='Цилиндр радиусом 5 футов и высотой 40 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='лист лунного семени', check_type='Спасбросок Телосложения', damage='2к10 излучением; половина при успехе', effect_summary='Создаёт вертикальный луч. Существа делают спасбросок при появлении луча, при перемещении области в их пространство, при входе или завершении хода внутри. Действием Магии в последующие ходы можно сдвигать цилиндр до 60 футов.', upcast='+1к10 урона за каждый уровень ячейки выше 2.', notes='Существо делает этот спасбросок не более одного раза за ход. Превращённая цель при провале возвращается в истинную форму и не может менять форму, пока не покинет луч.', author_description='Друид вызывает с неба луч, который особенно ненавидит тех, кто меняет форму. Забавно слышать это от людей, которые сами регулярно становятся медведями.', author_comment='Лунные друиды называют это природой. Я называю это семейной ссорой.' where slug='moonbeam';
update public.spell_catalog set name_ru='Бесследное передвижение', casting_time='Действие', spell_range='На себя', area='Эманация радиусом 30 футов', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='пепел сожжённой омелы', check_type='', damage='', effect_summary='Ты и выбранные тобой существа внутри ауры получают +10 к проверкам Ловкости (Скрытность) и не оставляют следов.', upcast='', notes='Бонус действует только пока существо находится в ауре.', author_description='Следопыт помогает всей группе исчезнуть с дороги без фейерверка и лекции о теории магии. Вот почему я люблю следопытов.', author_comment='Если с +10 кто-то всё равно шумит, оставьте его врагам. Естественный отбор тоже часть природы.' where slug='pass-without-trace';